<script>
    function toggleCandidateDrawer(show = true) {
      const drawer = document.getElementById('candidate-drawer');
      const backdrop = document.getElementById('drawer-backdrop');
      if (show) {
        drawer.classList.remove('translate-x-full');
        backdrop.classList.remove('opacity-0', 'pointer-events-none');
      } else {
        drawer.classList.add('translate-x-full');
        backdrop.classList.add('opacity-0', 'pointer-events-none');
      }
    }

    function selectRowCandidate(name, matric, dept, faculty, cgpa, ninHash, did, status) {
      document.getElementById('drawer-name').textContent = name;
      document.getElementById('drawer-matric').textContent = matric;
      document.getElementById('drawer-dept').textContent = dept;
      document.getElementById('drawer-faculty').textContent = faculty;
      document.getElementById('drawer-cgpa').textContent = cgpa;
      document.getElementById('drawer-ninhash').textContent = ninHash;
      document.getElementById('drawer-did').textContent = did;
      const statusPill = document.getElementById('drawer-status-pill');
      statusPill.textContent = status;
      toggleCandidateDrawer(true);
    }

    function toggleFilterPanel() {
      const panel = document.getElementById('advanced-filters-panel');
      panel.classList.toggle('hidden');
    }

    function copyToClipboard(text, elementId) {
      navigator.clipboard.writeText(text);
      const el = document.getElementById(elementId);
      const originalHtml = el.innerHTML;
      el.innerHTML = '<span class="material-symbols-outlined text-[14px] text-on-tertiary-container">done</span><span class="text-on-tertiary-container font-audit-mono text-audit-mono">Copied</span>';
      setTimeout(() => {
        el.innerHTML = originalHtml;
      }, 1500);
    }
